import dns from 'dns';
import { BlockList, isIP } from 'net';
export class PrivateIPError extends Error {
    constructor(hostname, ip) {
        super(`Blocked: ${hostname} resolves to private IP ${ip}`);
        this.hostname = hostname;
        this.ip = ip;
        this.name = 'PrivateIPError';
    }
}
const privateIPBlockList = new BlockList();
for (const [network, prefix] of [
    ['0.0.0.0', 8],
    ['10.0.0.0', 8],
    ['100.64.0.0', 10],
    ['127.0.0.0', 8],
    ['169.254.0.0', 16],
    ['172.16.0.0', 12],
    ['192.0.0.0', 24],
    ['192.0.2.0', 24],
    ['192.88.99.0', 24],
    ['192.168.0.0', 16],
    ['198.18.0.0', 15],
    ['198.51.100.0', 24],
    ['203.0.113.0', 24],
    ['224.0.0.0', 4],
    ['240.0.0.0', 4],
]) {
    privateIPBlockList.addSubnet(network, prefix, 'ipv4');
}
// ::/96 covers ::, ::1 and the deprecated IPv4-compatible ::a.b.c.d form; the NAT64 and
// 6to4 prefixes embed an arbitrary IPv4 address, so they are blocked wholesale rather
// than unwrapped - they are transition mechanisms, never a legitimate API destination
for (const [network, prefix] of [
    ['::', 96],
    ['64:ff9b::', 96],
    ['64:ff9b:1::', 48],
    ['100::', 64],
    ['2001::', 32],
    ['2001:2::', 48],
    ['2001:10::', 28],
    ['2001:20::', 28],
    ['2001:db8::', 32],
    ['2002::', 16],
    ['3fff::', 20],
    ['5f00::', 16],
    ['fc00::', 7],
    ['fe80::', 10],
    ['fec0::', 10],
    ['ff00::', 8],
]) {
    privateIPBlockList.addSubnet(network, prefix, 'ipv6');
}
export function isPrivateIP(ip) {
    const ipType = isIP(ip);
    if (ipType === 0)
        return true;
    // handle IPv4-mapped IPv6 (::ffff:x.x.x.x) - extract IPv4 and check that
    const lower = ip.toLowerCase();
    if (lower.startsWith('::ffff:') && ip.includes('.')) {
        const ipv4 = ip.slice(7);
        if (isIP(ipv4) === 4) {
            return privateIPBlockList.check(ipv4, 'ipv4');
        }
        return true; // malformed IPv4 part = block
    }
    return privateIPBlockList.check(ip, ipType === 4 ? 'ipv4' : 'ipv6');
}
// custom lookup that validates resolved IPs before returning them
// the IP returned here is the EXACT IP the socket will connect to (no TOCTOU)
// resolves all addresses so dual-stack fallback keeps working; rejects if any is private
export function safeLookup(hostname, options, callback) {
    dns.lookup(hostname, Object.assign(Object.assign({}, options), { all: true }), (err, addresses) => {
        const fail = (e) => {
            if (options.all) {
                callback(e, []);
            }
            else {
                callback(e, '', 0);
            }
        };
        if (err) {
            fail(err);
            return;
        }
        if (!Array.isArray(addresses)) {
            fail(new Error('unexpected DNS lookup result'));
            return;
        }
        const [first] = addresses;
        if (!first) {
            fail(new Error('unexpected DNS lookup result'));
            return;
        }
        for (const { address } of addresses) {
            if (typeof address !== 'string' || isPrivateIP(address)) {
                fail(new PrivateIPError(hostname, address));
                return;
            }
        }
        if (options.all) {
            callback(null, addresses);
        }
        else {
            callback(null, first.address, first.family);
        }
    });
}
